def count_tile_sequences(tiles):
 from collections import Counter
 counts=Counter(tiles)
 def search():
  answer=0
  for letter in counts:
   if counts[letter]:
    answer+=1;counts[letter]-=1;answer+=search();counts[letter]+=1
  return answer
 return search()

